Byte Streams.code:
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;

public class ByteStreamDemo {
    public static void main(String[] args) throws IOException {
        try (FileInputStream input = new FileInputStream("input.jpg");
             FileOutputStream output = new FileOutputStream("copy.jpg")) {

            byte[] buffer = new byte[1024];
            int bytesRead;

            while ((bytesRead = input.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead);
            }
        }
    }
}

Character Streams.code:
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public class CharacterStreamDemo {
    public static void main(String[] args) throws IOException {
        try (FileReader reader = new FileReader("input.txt");
             FileWriter writer = new FileWriter("output.txt")) {

            int character;
            while ((character = reader.read()) != -1) {
                writer.write(character);
            }
        }
    }
}

Exception Handling in File Operations.code:
import java.io.FileReader;
import java.io.IOException;

public class FileExceptionDemo {
    public static void main(String[] args) {
        try (FileReader reader = new FileReader("missing.txt")) {
            System.out.println("File opened successfully");
        } catch (IOException e) {
            System.out.println("File operation failed: " + e.getMessage());
        }
    }
}
